    max-width: 600px;
}

.notifications-section h3 {
    margin-bottom: 1rem;
}

.notifications-section h4 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
}

.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    padding: 0.5rem 0;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding-left: 0.25rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    padding: 0.4rem 0;
}

.channel-item input[type="checkbox"] {
    width: 16px;
