arguments.file_text:
@namespace sv_bbeba79c76024b49bff8f769a823c1f3.Components.Pages.Settings
@using sv_bbeba79c76024b49bff8f769a823c1f3.Services

<div class="security-section">
    @if (_loading)
    {
        <p>Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
                <span>Change Password</span>
                <span class="expand-icon">@(_passwordExpanded ? "▾" : "▸")</span>
            </button>
            @if (_passwordExpanded)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <p class="error-message">@_passwordError</p>
                    }
                    @if (_passwordSuccess)
                    {
                        <p class="success-message">Password updated successfully!</p>
                    }
                    <button class="btn-primary" @onclick="UpdatePasswordAsync">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <h4>Two-Factor Authentication</h4>
            <div class="tfa-status">
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "● Enabled" : "○ Disabled")
                </span>
                <label class="toggle-item">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span>@(_twoFactorEnabled ? "Disable 2FA" : "Enable 2FA")</span>
                </label>
            </div>
            @if (_settings?.LastPasswordChange is not null)
            {
                <p class="last-change">Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h4>Active Sessions</h4>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != _sessions.FirstOrDefault())
                                {
                                    <button class="btn-danger-sm" @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation="true">
                    <h4>Confirm Session Revocation</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn-danger" @onclick="ConfirmRevokeAsync">Revoke Session</button>
                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _passwordExpanded;
    private bool _twoFactorEnabled;
    private bool _passwordSuccess;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = new();
    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _sessions = _settings.Sessions;
        _loading = false;
    }

    private async Task UpdatePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password cannot be empty.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _passwordSuccess = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.Remove(_sessionToRevoke);
            _sessionToRevoke = null;
        }
    }
}

.security-section {
    max-width: 700px;
}

.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #fafafa;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
}

.panel-header:hover {
    background: #f0f0f0;
}

.expand-icon {
    font-size: 0.9rem;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.3rem;
    font-size: 0.9rem;
}

.form-group input {
    width: 100%;
    max-width: 350px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.error-message {
    color: #c62828;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.success-message {
    color: #2e7d32;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.tfa-section {
    margin-bottom: 1.5rem;
}

.tfa-section h4 {
    margin-bottom: 0.75rem;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.status-indicator {
    font-weight: 600;
    font-size: 0.9rem;
}

.status-indicator.enabled {
    color: #2e7d32;
}

.status-indicator.disabled {
    color: #9e9e9e;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.last-change {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #666;
}

.sessions-section h4 {
    margin-bottom: 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
    font-size: 0.9rem;
}

.sessions-table th {
    background: #fafafa;
    font-weight: 600;
}

.current-badge {
    font-size: 0.8rem;
    background: #e3f2fd;
    color: #1565c0;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
    font-weight: 500;
}

.btn-danger-sm {
    padding: 0.3rem 0.6rem;
    background: #ffebee;
    color: #c62828;
