toolArgs.file_text:
.security-section {
    max-width: 700px;
}

.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #fafafa;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 600;
}

.panel-header:hover {
    background: #f0f0f0;
}

.expand-icon {
    font-size: 0.9rem;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.3rem;
    font-size: 0.9rem;
}

.form-group input {
    width: 100%;
    max-width: 350px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.error-message {
    color: #c62828;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.success-message {
    color: #2e7d32;
    font-size: 0.85rem;
    margin-bottom: 0.5rem;
}

.tfa-section {
    margin-bottom: 1.5rem;
}

.tfa-section h4 {
    margin-bottom: 0.75rem;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.status-indicator {
    font-weight: 600;
    font-size: 0.9rem;
}

.status-indicator.enabled {
    color: #2e7d32;
}

.status-indicator.disabled {
    color: #9e9e9e;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

.last-change {
    margin-top: 0.5rem;
    font-size: 0.85rem;
    color: #666;
}

.sessions-section h4 {
    margin-bottom: 0.75rem;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
    font-size: 0.9rem;
}

.sessions-table th {
    background: #fafafa;
    font-weight: 600;
}

.current-badge {
    font-size: 0.8rem;
    background: #e3f2fd;
    color: #1565c0;
    padding: 0.2rem 0.5rem;
    border-radius: 3px;
    font-weight: 500;
}

.btn-danger-sm {
    padding: 0.3rem 0.6rem;
    background: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.8rem;
}

.btn-danger-sm:hover {
    background: #ffcdd2;
}

.dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

.dialog h4 {
    margin-bottom: 0.75rem;
}

.dialog p {
    margin-bottom: 1rem;
    color: #555;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

.btn-danger {
    padding: 0.5rem 1rem;
    background: #c62828;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-weight: 500;
}

.btn-danger:hover {
    background: #b71c1c;
}

