@namespace sv_bbeba79c76024b49bff8f769a823c1f3.Components.Pages.Settings
@using sv_bbeba79c76024b49bff8f769a823c1f3.Services

<div class="appearance-section">
    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <h3>Theme</h3>
        <div class="radio-group">
            @foreach (var theme in _themes)
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>

        <h3>Font Size</h3>
        <div class="radio-group">
            @foreach (var size in _fontSizes)
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>

        <h3>Language</h3>
        <div class="form-group">
            <select @bind="_language">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <span>Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="preview-area @GetPreviewClasses()">
            <h4>Live Preview</h4>
            <div class="preview-content">
                <p class="preview-heading">Sample Heading</p>
                <p class="preview-text">This is how your content will look with the selected settings.</p>
                <button class="preview-button">Sample Button</button>
            </div>
        </div>

        <div class="form-actions">
            <button class="btn-primary" @onclick="SaveAsync">Save</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast-success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _showSuccess;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
        if (_compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

.appearance-section {
    max-width: 600px;
}

.appearance-section h3 {
    margin-top: 1.25rem;
    margin-bottom: 0.75rem;
    font-size: 1rem;
}

.appearance-section h3:first-child {
    margin-top: 0;
}

.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

.radio-item input[type="radio"] {
    cursor: pointer;
}

.form-group select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    min-width: 200px;
}

.toggle-group {
    margin-top: 1.25rem;
}

.toggle-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
}

.toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
}

/* Live Preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.3s ease;
}

.preview-area h4 {
    margin-bottom: 0.75rem;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #999;
}

.preview-content {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.preview-heading {
    font-weight: 600;
    margin: 0;
}

.preview-text {
    margin: 0;
}

.preview-button {
    align-self: flex-start;
    padding: 0.4rem 0.8rem;
    border-radius: 4px;
    border: 1px solid #ccc;
    cursor: pointer;
    margin-top: 0.25rem;
}

/* Theme variants */
.preview-area.theme-light {
    background: #ffffff;
    color: #333;
}

.preview-area.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-area.theme-dark .preview-button {
    background: #333;
    color: #e0e0e0;
    border-color: #555;
}

.preview-area.theme-dark h4 {
    color: #888;
}

.preview-area.theme-system {
    background: #f5f5f5;
    color: #333;
}

/* Font size variants */
.preview-area.font-small .preview-heading {
    font-size: 0.95rem;
}
.preview-area.font-small .preview-text {
    font-size: 0.8rem;
}

.preview-area.font-medium .preview-heading {
    font-size: 1.1rem;
}
.preview-area.font-medium .preview-text {
    font-size: 0.95rem;
}

.preview-area.font-large .preview-heading {
    font-size: 1.3rem;
}
.preview-area.font-large .preview-text {
    font-size: 1.1rem;
}

/* Compact mode */
.preview-area.compact {
    padding: 0.75rem;
}

.preview-area.compact .preview-content {
    gap: 0.25rem;
}

.form-actions {
    margin-top: 1.5rem;
}

.toast-success {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    background-color: #c8e6c9;
    color: #2e7d32;
    border-radius: 4px;
    font-weight: 500;
}

