@page "/settings"
@using sv_bbeba79c76024b49bff8f769a823c1f3.Components.Pages.Settings
@using sv_bbeba79c76024b49bff8f769a823c1f3.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="section => _activeSection = section" />

    <main class="settings-content">
        <h2>@_activeSection</h2>

        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "Notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "Security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "Appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 80px);
    gap: 0;
}

.settings-content {
    flex: 1;
    padding: 2rem;
}

.settings-content h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
    color: #333;
}

/* Shared button styles */
:deep(.btn-primary) {
    padding: 0.5rem 1.25rem;
    background-color: #1565c0;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

:deep(.btn-primary:hover) {
    background-color: #0d47a1;
}

:deep(.btn-secondary) {
    padding: 0.5rem 1.25rem;
    background-color: white;
    color: #555;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

:deep(.btn-secondary:hover) {
    background-color: #f5f5f5;
}

